import {
  type CreateWarehouseSpaceInput,
  toCalendarDate,
  type WarehouseSpace as WarehouseSpaceDto,
} from '@deadspace/shared';
import type { PrismaClient } from '../db.js';
import type { Prisma, WarehouseSpace } from '../generated/prisma/client.js';
import type { WarehouseSpaceFacts } from '../matching/warehouse.js';

/** Maps validated input to columns. The *Geog column is generated by the database. */
export function toWarehouseSpaceCreateData(input: CreateWarehouseSpaceInput): Prisma.WarehouseSpaceCreateInput {
  const { location, ...rest } = input;
  return {
    ...rest,
    locationLabel: location.label,
    locationLat: location.lat,
    locationLng: location.lng,
  };
}

export function createWarehouseSpace(prisma: PrismaClient, input: CreateWarehouseSpaceInput): Promise<WarehouseSpace> {
  return prisma.warehouseSpace.create({ data: toWarehouseSpaceCreateData(input) });
}

export function findWarehouseSpaceById(prisma: PrismaClient, id: string): Promise<WarehouseSpace | null> {
  return prisma.warehouseSpace.findUnique({ where: { id } });
}

export function findWarehouseSpacesByIds(prisma: PrismaClient, ids: readonly string[]): Promise<WarehouseSpace[]> {
  return prisma.warehouseSpace.findMany({ where: { id: { in: [...ids] } } });
}

/** Row → API shape: location regrouped, Decimal money as number, calendar dates as YYYY-MM-DD. */
export function toWarehouseSpaceDto(row: WarehouseSpace): WarehouseSpaceDto {
  return {
    id: row.id,
    status: row.status,
    companyName: row.companyName,
    contactName: row.contactName,
    contactEmail: row.contactEmail,
    location: { label: row.locationLabel, lat: row.locationLat, lng: row.locationLng },
    quantityAvailable: row.quantityAvailable,
    minPallets: row.minPallets,
    availableFrom: toCalendarDate(row.availableFrom),
    availableTo: toCalendarDate(row.availableTo),
    minStorageDays: row.minStorageDays,
    temperatureControlled: row.temperatureControlled,
    foodGrade: row.foodGrade,
    pricingPeriod: row.pricingPeriod,
    pricePerPalletPerPeriod: row.pricePerPalletPerPeriod.toNumber(),
    handlingFeePerPallet: row.handlingFeePerPallet?.toNumber() ?? null,
    notes: row.notes,
    createdAt: row.createdAt.toISOString(),
    updatedAt: row.updatedAt.toISOString(),
  };
}

/** Row → the plain facts the pure matcher reads (Decimal money as number, dates as UTC midnights). */
export function toWarehouseSpaceFacts(row: WarehouseSpace): WarehouseSpaceFacts {
  return {
    id: row.id,
    status: row.status,
    quantityAvailable: row.quantityAvailable,
    minPallets: row.minPallets,
    availableFrom: row.availableFrom,
    availableTo: row.availableTo,
    minStorageDays: row.minStorageDays,
    temperatureControlled: row.temperatureControlled,
    foodGrade: row.foodGrade,
    pricingPeriod: row.pricingPeriod,
    pricePerPalletPerPeriod: row.pricePerPalletPerPeriod.toNumber(),
    handlingFeePerPallet: row.handlingFeePerPallet?.toNumber() ?? null,
  };
}
